package record

import (
	json "encoding/json/v2"
	"testing"
)

// These literals are retained v1 records, not encodings generated by the codec
// under test. Bindings cover the decoded, typed record's canonical encoding.
const recoveryCompatSource = `{"version":1,"id":"amber","stdout":"first\n\u003c\u0026\"\u2028\nlast\n","stderr":"","exit_code":0,"position":[0,0]}`
const recoveryCompatBinding = "12c5f79f4e150c707f9cad58681455f7f9d4abb6de102f46f0f05c18fcc88fb9"

func TestRecoveryIssuedCursorCompat(t *testing.T) {
	t.Parallel()
	const digest = "00a940f03a637a4e4d80335c02e974cf5369446eef4bc2cc366061fc8d2ddf2e"
	const issued = `{"version":1,"id":"apple","stdout":"","stderr":"","exit_code":0,"source":"amber","position":[6,0],"stream":"stdout","cursor_digest":"00a940f03a637a4e4d80335c02e974cf5369446eef4bc2cc366061fc8d2ddf2e","binding":"12c5f79f4e150c707f9cad58681455f7f9d4abb6de102f46f0f05c18fcc88fb9"}`
	cursor, err := Decode([]byte(issued), "apple", true, nil)
	if err != nil {
		t.Fatal(err)
	}
	source, err := Decode([]byte(recoveryCompatSource), cursor.Source, true, nil)
	if err != nil {
		t.Fatal(err)
	}
	if Binding(source) != cursor.Binding || CursorDigest(cursor) != digest {
		t.Fatal("issued cursor lost its source binding or digest")
	}
	data, err := json.Marshal(cursor, LegacyJSON)
	if err != nil || string(data) != issued {
		t.Fatalf("canonical cursor = %s, %v; want %s", data, err, issued)
	}
	// Cursor identity is deliberately outside its digest, but position is bound.
	cursor.ID = "arch"
	if CursorDigest(cursor) != digest {
		t.Fatal("cursor handle changed its digest")
	}
	cursor.Position[0]++
	if Validate(cursor) == nil {
		t.Fatal("altered issued cursor accepted")
	}
}

func TestReadRecordCanonicalCompat(t *testing.T) {
	for _, input := range []string{recoveryCompatSource, `{"changes":null,"stderr":"","exit_code":0,"stdout":"first\n<&\"\u2028\nlast\n","id":"amber","version":1}`} {
		value, err := Decode([]byte(input), "amber", true, nil)
		if err != nil {
			t.Fatal(err)
		}
		data, err := Encode(value)
		if err != nil || string(data) != recoveryCompatSource || Binding(value) != recoveryCompatBinding {
			t.Fatalf("canonical source: %s, %v", data, err)
		}
	}
}
